const PREMIUM_ROLES=new Set(["trial","premium","vip","admin","cancelled_active"]);
function canAccessPremiumPlaces(entitlement){if(entitlement?.premium===true)return true;const role=String(entitlement?.role||entitlement?.status||entitlement?.subscription_status||"free");if(role==="cancelled_active"){const end=entitlement?.current_period_ends_at||entitlement?.expires_at;return !end||new Date(end).getTime()>Date.now()}return PREMIUM_ROLES.has(role)}
function getPlaceAccessTier(entitlement){return canAccessPremiumPlaces(entitlement)?"premium":"free"}
function getAccessiblePlaces(allPlaces,entitlement){const premium=canAccessPremiumPlaces(entitlement);return allPlaces.filter(place=>place.enabled&&(place.accessTier==="free"||premium))}
const nameCounts=new Map();for(const place of PLACE_REGISTRY){const name=place.name.toLocaleLowerCase("sv");nameCounts.set(name,(nameCounts.get(name)||0)+1)}const duplicateNames=new Set([...nameCounts].filter(([,count])=>count>1).map(([name])=>name));
function getPlaceDisplayName(place){return duplicateNames.has(place.name.toLocaleLowerCase("sv"))?(place.municipality?place.name+" · nära "+place.municipality:place.name+", "+place.area):place.name}
function placeTuple(place){return [place.name,place.area,place.region,place.latitude,place.longitude,place.id,place.accessTier]}
const ENABLED_PLACES=PLACE_REGISTRY.filter(place=>place.enabled);const PLACES=ENABLED_PLACES.map(placeTuple);export {PLACE_REGISTRY,ENABLED_PLACES,PLACES,canAccessPremiumPlaces,getPlaceAccessTier,getAccessiblePlaces,getPlaceDisplayName,placeTuple};
